set -u; umask 077; F="$1"; N="$2"; U="$3"; T="$4"; ID="$5"; S="${TMPDIR:-/tmp}/vidiq-upload-$ID"; H=" Run this on the computer that has the file, or ask the user to upload it with the vidiq_file_upload picker."; fail() { printf "vidIQ upload stopped: %s\n" "$*" >&2; exit 1; }; case "$F" in /*) ;; "~/"*) [ -n "${HOME:-}" ] || fail "HOME is not set in this shell. Call vidiq_video_upload with localFile again with the absolute path."; F="$HOME/${F#??}" ;; *) F="$PWD/$F"; H=" The path was relative to the folder this ran in: run this same command from the folder the path starts from, or call vidiq_video_upload with localFile again with the absolute path." ;; esac; c() { curl -q -sS -g --connect-timeout 30 "$@"; }; code() { tr -d "\r" | sed -n "s/^HTTP\/[0-9.]* \([0-9][0-9][0-9]\).*/\1/p" | tail -n 1; }; hdr() { tr -d "\r" | grep -i "^$1:" | tail -n 1 | sed "s/^[^:]*: *//"; }; status() { c -m 60 -o /dev/null -D - -X PUT -H "Content-Length: 0" -H "Content-Range: bytes */$N" "$X" || fail "lost the connection to storage. Run this same command again to resume."; }; [ -f "$F" ] && [ -r "$F" ] || fail "cannot read $F from this shell.$H"; A=$(wc -c < "$F" | tr -d " "); [ "$A" = "$N" ] || fail "$F has $A bytes, not $N. Call vidiq_video_upload with localFile again with its current size."; case "$(dd if="$F" bs=1 skip=4 count=4 2>/dev/null)" in ftyp|moov|mdat|wide|free|skip) ;; *) fail "$F is not an MP4 or MOV file." ;; esac; X=$(cat "$S" 2>/dev/null); Q=""; [ -n "$X" ] && { Q=$(status) || exit 1; }; case "$(printf "%s\n" "$Q" | code)" in 200|201|308|408|429|5??) ;; *) X="" ;; esac; if [ -z "$X" ]; then R=$(c -m 60 -o /dev/null -D - -X POST -H "x-goog-resumable: start" -H "x-upload-content-type: $T" -H "x-upload-content-length: $N" -H "Content-Length: 0" "$U") || fail "cannot reach storage.googleapis.com from this shell."; X=$(printf "%s\n" "$R" | hdr location); [ -n "$X" ] || fail "storage refused the upload link in this command; it expires an hour after it was issued. Call vidiq_video_upload with localFile again to get a new command."; { printf "%s\n" "$X" > "$S"; } 2>/dev/null; Q=$(status) || exit 1; fi; case "$(printf "%s\n" "$Q" | code)" in 200|201) ;; 308) R=$(printf "%s\n" "$Q" | hdr range | sed "s/.*-//"); O=$(( ${R:--1} + 1 )); echo "vidIQ upload: $(( O / 1000000 )) of $(( N / 1000000 )) MB already stored, sending the rest"; W=$(c -Y 1 -y 120 -o /dev/null -w "%{http_code}" -X PUT -C "$O" -T "$F" "$X"); case "$W" in 200|201) ;; *) fail "interrupted before the upload finished. Run this same command again to resume." ;; esac ;; *) fail "storage gave an unexpected answer. Run this same command again to resume." ;; esac; echo "vidIQ upload complete. Now call vidiq_video_upload with {\"uploadId\":\"$ID\"}."
